class Parent {
    public void show() {
        System.out.println("parent");
    }
}
class Child extends Parent {
    void show() {
        System.out.println("child");
    }
}
public class Main {
    public static void main(String[] args) {
        Parent p = new Child();
        p.show();
    }
}
